// Generated by `npm run build:wasm` (wasm-pack) into src/wasm/
import init, { apply_filter, validate_csv, validate_xlsx } from '../wasm/rust_core.js';

const ctx = self as any;
let wasmMemory: WebAssembly.Memory | undefined;
let initMs = 0;

const ready = (async () => {
  const t = performance.now();
  const exports = await init();
  wasmMemory = exports.memory;
  initMs = performance.now() - t;
})();

ctx.onmessage = async (e: MessageEvent) => {
  const m = e.data;
  try {
    await ready;
    if (m.kind === 'ping') {
      ctx.postMessage({ id: m.id, initMs });
      return;
    }
    // Timed region includes copying the input into WASM memory and the result back out (the JS<->WASM boundary cost).
    const t0 = performance.now();
    if (m.kind === 'image') {
      const out = apply_filter(new Uint8Array(m.pixels), m.width, m.height, m.filter);
      const processingMs = performance.now() - t0;
      ctx.postMessage({ id: m.id, processingMs, memoryBytes: wasmMemory?.buffer.byteLength, pixels: out.buffer }, [out.buffer]);
    } else {
      const json = m.kind === 'csv' ? validate_csv(new Uint8Array(m.bytes)) : validate_xlsx(new Uint8Array(m.bytes));
      const report = JSON.parse(json);
      ctx.postMessage({ id: m.id, processingMs: performance.now() - t0, memoryBytes: wasmMemory?.buffer.byteLength, report });
    }
  } catch (err) {
    ctx.postMessage({ id: m.id, error: String(err) });
  }
};
